INSERT INTO OPPORTUNITIES (opp_id, name, amount, probability, stage, strategic_account, no_economic_buyer, competitor_present, security_legal_blocked, procurement_not_started, champion_risk, inactive_21d, conflicting_signals, days_since_activity, close_date, notes) VALUES
('OPP-001', 'Meridian Health -- Platform Renewal', 5200000, 0.99, 'CONTRACT', TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 2, '2026-08-28'::DATE, 'Legal review complete, MSA redlines signed off 8/2. PO already raised in their system. CFO sponsored the renewal in the QBR. No competing vendor in the account. Rep expects countersignature this month.'),
('OPP-002', 'Northwind Logistics -- Analytics Expansion', 400000, 0.52, 'PROPOSAL', FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, 9, '2026-10-30'::DATE, 'Security review stalled three weeks on data residency question, no ETA from their InfoSec. Champion (Dir of Ops) is enthusiastic but VP Finance has not joined any call. Procurement portal registration not started. DataRival named by procurement as a reference bid they intend to collect.'),
('OPP-003', 'Castellan Insurance -- Claims AI Pilot', 750000, 0.58, 'NEGOTIATION', FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, TRUE, 5, '2026-11-13'::DATE, 'Stage says negotiation but no commercial terms have actually been discussed. Champion moved into a new role with narrower budget authority mid-cycle, and with that move nobody at Castellan currently owns the budget decision -- the Claims VP claims it, but spend of this size routes through an IT steering committee the Claims VP does not sit on. Claims VP wants full-department rollout; IT sponsor insists on a 10-seat pilot only -- the two have not reconciled scope. Incumbent vendor''s renewal is running in parallel.'),
('OPP-004', 'Quarry Steel -- Data Platform', 900000, 0.05, 'DISCOVERY', FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 44, '2026-09-25'::DATE, 'Champion resigned in June and joined a competitor. No response to three follow-ups since 6/23. Deal kept open at rep''s request pending one final executive email.'),
('OPP-005', 'Bluewater Resorts -- POS Analytics', 150000, 0.08, 'QUALIFICATION', FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 31, '2026-09-18'::DATE, 'Initial demo went fine but budget owner never identified. Contact went quiet after 7/6; two nudges unanswered. Seasonal business -- they may re-engage after peak season, not before close date.'),
('OPP-006', 'Halberd Financial -- License Renewal', 1100000, 0.97, 'CONTRACT', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 3, '2026-08-31'::DATE, 'Renewal paper with their legal for signature routing, expected back within two weeks. Usage grew 22% YoY, no open support escalations, no competitor activity.'),
('OPP-007', 'Sierra Foods -- Renewal + Seat Expansion', 680000, 0.96, 'CONTRACT', TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 4, '2026-09-11'::DATE, 'Named strategic account. Renewal plus 40-seat expansion verbally agreed with the COO; order form in their signature queue. Pricing already approved on our side.'),
('OPP-008', 'Atlas Freight -- Enterprise Rollout', 2400000, 0.93, 'NEGOTIATION', TRUE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, 7, '2026-10-16'::DATE, 'Rep has probability at 93% after exec dinner, but security architecture review is unfinished, procurement intake not filed, and RivalCo was on-site last month -- the CRM optimism and the open blockers do not tell the same story. Probable and messy at the same time.'),
('OPP-009', 'Pinnacle Media -- Contract Renewal', 320000, 0.92, 'CONTRACT', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 24, '2026-09-04'::DATE, 'Auto-renewal language in current contract; customer historically signs late with no drama. Nothing from their side in three-plus weeks, which matches last year''s pattern rather than signaling a problem.'),
('OPP-010', 'Redwood Biotech -- Data Cloud Renewal', 540000, 0.91, 'CONTRACT', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 6, '2026-09-30'::DATE, 'Renewal confirmed verbally by IT director; waiting on their new fiscal-year budget code to process the order. Support tickets trending down, adoption steady.'),
('OPP-011', 'Ironvale Mining -- Support Renewal', 210000, 0.98, 'CONTRACT', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 8, '2026-08-21'::DATE, 'Flat renewal, same terms as last year. Customer confirmed in writing; invoice requested for their AP calendar. Formality at this point.'),
('OPP-012', 'Concord Utilities -- Grid Analytics', 1800000, 0.45, 'PROPOSAL', TRUE, TRUE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, 28, '2026-12-11'::DATE, 'Regulated-utility security addendum still with their counsel, four weeks now. Economic buyer (VP Grid Ops) has delegated all calls to an analyst. Procurement says RFP may be required. No substantive contact since mid-July.'),
('OPP-013', 'Vantage Retail -- Personalization Suite', 950000, 0.6, 'NEGOTIATION', FALSE, TRUE, TRUE, FALSE, FALSE, TRUE, FALSE, TRUE, 10, '2026-11-06'::DATE, 'CMO sponsor reorged into a regional role; replacement not named. Merchandising team pushing to close this quarter while finance asks why the project exists at all -- directly contradictory signals in the same week. PersonaLab ran a competing pilot in Q2.'),
('OPP-014', 'Helios Energy -- Forecasting Platform', 1250000, 0.35, 'PROPOSAL', FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, TRUE, FALSE, 26, '2026-12-18'::DATE, 'Five open risk signals. SOC2 addendum questions unanswered, no budget owner on record, procurement intake not started, incumbent forecasting vendor lobbying to extend, and the account has been dark for almost four weeks.'),
('OPP-015', 'Argent Bank -- Risk Modeling Workbench', 3100000, 0.68, 'NEGOTIATION', TRUE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, 6, '2026-11-27'::DATE, 'Model-risk-management review open with two rounds of questions outstanding. Procurement will not open intake until MRM clears. Business unit says signed by Thanksgiving; risk office says no vendor decisions before year-end -- both are in the CRM. QuantEdge shortlisted alongside us.'),
('OPP-016', 'Trailhead Apparel -- Customer 360', 880000, 0.75, 'PROPOSAL', TRUE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 11, '2026-10-23'::DATE, 'Strategic logo for the retail vertical. Proposal well received; CDP incumbent responded with a discounted renewal offer. Exec sponsor engaged and responsive.'),
('OPP-017', 'Keystone Manufacturing -- Supply Chain AI', 1500000, 0.66, 'DISCOVERY', TRUE, TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, 13, '2026-12-04'::DATE, 'Named strategic account, early cycle. Plant-level buy-in is strong; corporate budget owner not yet identified. Long procurement runway typical for this account -- flagged early, not yet blocking.'),
('OPP-018', 'Lumen Studios -- Media Asset Search', 260000, 0.4, 'QUALIFICATION', FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 14, '2026-11-20'::DATE, 'Post-production leads love the demo; nobody with budget authority has been in a meeting yet. Studio is mid-slate, decisions move slowly until wrap.'),
('OPP-019', 'Copperline Telecom -- Churn Analytics', 620000, 0.72, 'PROPOSAL', FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 8, '2026-10-09'::DATE, 'Technical eval scored us first of three. TelcoMetrics remains in the process at the CIO''s insistence. Commercial proposal delivered, awaiting their scoring committee.'),
('OPP-020', 'Foxglove Pharma -- Trial Data Hub', 1050000, 0.55, 'PROPOSAL', FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 12, '2026-11-27'::DATE, 'GxP validation questionnaire in progress with our compliance team, their QA has follow-ups queued. Procurement will not engage until QA signs off. Sponsor steady, timeline realistic for pharma.'),
('OPP-021', 'Marlowe & Finch -- Legal Doc Intelligence', 190000, 0.3, 'DISCOVERY', FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 25, '2026-12-11'::DATE, 'Two partners saw the demo, neither owns the tech budget. Firm is mid-trial on a major matter; contact said to circle back in September and has been quiet since.'),
('OPP-022', 'Stonebridge Credit Union -- Fraud Scoring', 430000, 0.85, 'NEGOTIATION', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 4, '2026-09-18'::DATE, 'Terms agreed in principle; final pricing memo with their CFO. Reference call with a peer credit union completed and went smoothly. No open objections.'),
('OPP-023', 'Aurora Hospitality -- Guest Data Platform', 350000, 0.25, 'QUALIFICATION', FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, FALSE, 16, '2026-12-18'::DATE, 'Early exploration driven by a new VP of Digital who has not yet secured budget. HotelTech incumbent has a multi-year contract with an early-exit clause under review. Procurement not aware of the initiative.'),
('OPP-024', 'Granite Peak Builders -- Project Analytics', 780000, 0.62, 'PROPOSAL', FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, TRUE, 9, '2026-10-30'::DATE, 'Champion (IT Director) survived a reorg but lost two of five direct reports. Ops leadership calls this a top-three initiative while the CFO''s office lists it under discretionary spend eligible for deferral -- same week, different decks.'),
('OPP-025', 'Silverbirch Education -- Enrollment Insights', 240000, 0.48, 'QUALIFICATION', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 23, '2026-11-13'::DATE, 'Positive pilot readout in early July, then summer break silence -- expected in education, admissions team returns mid-August. Pilot metrics already shared with their cabinet.'),
('OPP-026', 'Harborview Health -- Imaging Archive', 1400000, 0.78, 'NEGOTIATION', TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 5, '2026-10-16'::DATE, 'Strategic healthcare account. BAA and HIPAA security rider in legal review -- normal cycle time for them is 3-4 weeks and we are in week two. Clinical and IT sponsors aligned.'),
('OPP-027', 'Nimbus Gaming -- Player Telemetry', 165000, 0.2, 'DISCOVERY', FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 15, '2026-12-04'::DATE, 'Analytics lead ran a self-serve trial and liked it. Studio evaluating an open-source stack in parallel. No budget conversation yet; studio funding tied to next title milestone.'),
('OPP-028', 'Cobalt Chemicals -- ESG Reporting', 510000, 0.83, 'PROPOSAL', FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, 7, '2026-09-25'::DATE, 'Sustainability office selected us after a three-vendor bake-off. Procurement intake opens next cycle per their policy -- known, dated, and on their calendar. Sponsor responsive.'),
('OPP-029', 'Wrenfield Logistics -- Route Optimization', 290000, 0.15, 'QUALIFICATION', FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 35, '2026-11-20'::DATE, 'Original champion moved to a competitor in July. Operations analyst who inherited the eval has no purchasing authority and has not replied in five weeks.'),
('OPP-030', 'Juniper Robotics -- Fleet Data Platform', 830000, 0.7, 'PROPOSAL', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 6, '2026-10-23'::DATE, 'Engineering VP calls us the presumptive choice; the same VP''s staff meeting notes (shared by champion) list the project as paused pending Series C close. CRM probability reflects the VP''s verbal, not the board timeline.');
INSERT INTO MODEL_RUNS (run_id, opp_id, policy, threshold, tier, model, verdict, primary_blocker, next_best_action, reasoning, input_tokens, output_tokens, credits, latency_ms, error) VALUES
('reference|OPP-001', 'OPP-001', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'NO_ACTION_NEEDED', 'NONE', 'Monitor for countersignature and ensure contract execution is completed this month as expected.', 'This opportunity meets all criteria for no action needed: it is in CONTRACT stage with no active risk flags and a 0.99 close probability. Legal review is complete, the PO is raised, and CFO sponsorship confirms executive alignment. The deal is effectively won and awaiting final paperwork.', 531, 131, 0.0021348, 6438, NULL),
('reference|OPP-002', 'OPP-002', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'SECURITY_LEGAL', 'Escalate the data residency blocker by arranging a joint call between your security architect and their InfoSec lead with a clear decision deadline.', 'The security review has been stalled for three weeks with no resolution timeline, blocking all downstream progress including procurement and economic buyer engagement. Multiple compounding risks exist—no access to the VP Finance economic buyer, competitor present, and procurement not initiated—but none can advance until the security impasse is resolved. The 52% probability and proposal stage with these flags make this deal highly vulnerable without immediate intervention.', 565, 206, 0.002871, 8972, NULL),
('reference|OPP-003', 'OPP-003', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'ECONOMIC_BUYER', 'Facilitate a joint scoping meeting with the Claims VP and IT sponsor to align on pilot scope and identify the actual budget authority before any commercial discussion.', 'The deal is marked as negotiation stage but lacks a clear economic buyer after the champion''s role change, and no commercial terms have been discussed. The conflicting scope expectations between Claims VP and IT sponsor, combined with unclear budget routing through a steering committee, create fundamental deal structure risk. The parallel incumbent renewal adds urgency to resolving buyer alignment before competitive displacement occurs.', 602, 157, 0.0024966000000000003, 7450, NULL),
('reference|OPP-004', 'OPP-004', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'NO_ACTION_NEEDED', 'CHAMPION_LOSS', 'Close-lost this opportunity and focus resources on active deals with engaged stakeholders.', 'The close probability is 0.05, which meets the threshold for a deal that is effectively dead. The champion has left for a competitor and there has been no response in 44 days despite multiple follow-up attempts. No intervention will change this outcome.', 522, 132, 0.0021276, 7646, NULL),
('reference|OPP-005', 'OPP-005', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'NO_ACTION_NEEDED', 'NONE', 'Mark the opportunity as lost or push the close date beyond peak season to reflect the true sales cycle.', 'The CRM close probability of 0.08 indicates this deal is effectively dead and falls below the 0.1 threshold requiring no action. The contact has been unresponsive for over a month, no economic buyer was ever identified, and the seasonal business timing makes re-engagement unlikely before the current close date. No sales intervention will meaningfully change this outcome.', 538, 149, 0.0023094, 7063, NULL),
('reference|OPP-006', 'OPP-006', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'NO_ACTION_NEEDED', 'NONE', 'Monitor signature routing and confirm receipt within the two-week window.', 'This opportunity is in CONTRACT stage with 0.97 close probability and no active risk flags, meeting the criteria for a deal that is effectively won. Usage growth and absence of competitor activity further support the renewal momentum, with only administrative signature routing remaining.', 517, 116, 0.0019746, 5764, NULL),
('reference|OPP-007', 'OPP-007', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'NO_ACTION_NEEDED', 'NONE', 'Monitor signature queue status and confirm execution timeline with the COO''s office.', 'This opportunity is in CONTRACT stage with 0.96 close probability and no active risk flags, meeting the criteria for a deal that is effectively won. The order form is already in the customer''s signature queue with pricing approved, indicating all substantive selling work is complete and only administrative execution remains.', 517, 127, 0.0020736, 6998, NULL),
('reference|OPP-008', 'OPP-008', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'SECURITY_LEGAL', 'Escalate to complete the security architecture review immediately and file procurement intake in parallel before competitor advances.', 'The 93% probability conflicts sharply with three critical blockers: unfinished security review, no procurement intake, and active competitor presence. Security/legal is blocking forward motion while RivalCo remains engaged, creating execution risk despite executive enthusiasm. The conflicting signals flag confirms CRM optimism does not reflect deal reality.', 566, 140, 0.0022788, 6920, NULL),
('reference|OPP-009', 'OPP-009', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'INACTIVITY', 'Proactively reach out to confirm renewal intent and timeline, even if historical pattern suggests late signing.', 'The active_risk_flag ''inactive_21d'' triggers an AT_RISK verdict despite the high close probability and CONTRACT stage. While the notes indicate this inactivity matches historical behavior, 24 days without contact creates execution risk that requires intervention. A single confirmation touchpoint mitigates the risk of assumption-based forecasting.', 522, 144, 0.0022356, 8322, NULL),
('reference|OPP-010', 'OPP-010', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'NO_ACTION_NEEDED', 'NONE', 'Monitor for budget code receipt and execute contract when provided.', 'This opportunity is in CONTRACT stage with 91% close probability and no active risk flags, meeting all criteria for a deal effectively won. The IT director has verbally confirmed renewal and the only remaining step is an administrative budget code assignment. Recent activity and steady product adoption further support deal health.', 514, 121, 0.0020142, 6766, NULL),
('reference|OPP-011', 'OPP-011', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'NO_ACTION_NEEDED', 'NONE', 'Monitor contract execution and ensure invoice is delivered to accounts payable as requested.', 'This opportunity is in CONTRACT stage with 98% close probability and no active risk flags, meeting the criteria for a deal that is effectively won. The customer has confirmed in writing and requested an invoice, indicating commitment and readiness to complete the transaction.', 510, 127, 0.002061, 6086, NULL),
('reference|OPP-012', 'OPP-012', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'ECONOMIC_BUYER', 'Escalate immediately to executive sponsor to re-engage the VP of Grid Operations directly and confirm budget authority and project priority.', 'The economic buyer has disengaged and delegated to an analyst, eliminating deal control at the decision-maker level. Combined with 28 days of inactivity, stalled legal review, and unstarted procurement, this deal has lost momentum and executive sponsorship. Without the VP''s active involvement, neither the security addendum nor procurement process will advance.', 555, 177, 0.002592, 7455, NULL),
('reference|OPP-013', 'OPP-013', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'ECONOMIC_BUYER', 'Identify and engage the new CMO or acting executive owner before the close date to revalidate business case and budget authority.', 'The original executive sponsor has been reorged out with no named replacement, creating a critical gap in economic buyer coverage. Conflicting signals between merchandising urgency and finance skepticism indicate no aligned authority to approve the $950K deal. Without reestablishing executive sponsorship, the deal cannot progress through negotiation regardless of champion enthusiasm.', 558, 148, 0.0023364, 7497, NULL),
('reference|OPP-014', 'OPP-014', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'INACTIVITY', 'Re-engage immediately with the champion to confirm project status and schedule a meeting with the economic buyer within 72 hours.', 'This opportunity has been inactive for 26 days with five simultaneous risk flags including no identified economic buyer, blocked security/legal review, and competitor pressure. The prolonged silence is the most urgent signal that the deal may have stalled or deprioritized. Before addressing procurement, legal, or competitive issues, the team must first re-establish active engagement to determine if the opportunity is still viable.', 556, 159, 0.0024318, 7707, NULL),
('reference|OPP-015', 'OPP-015', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'SECURITY_LEGAL', 'Escalate to executive sponsor to resolve the two outstanding MRM question rounds and align business unit and risk office timelines before procurement can begin.', 'The deal is blocked at model-risk-management review with two rounds of questions still open, and procurement cannot start until MRM clears. The conflicting internal timelines (Thanksgiving vs. year-end) and presence of QuantEdge as a competitor create additional pressure, but the MRM gate is the immediate bottleneck preventing forward motion.', 568, 169, 0.0025434, 7058, NULL),
('reference|OPP-016', 'OPP-016', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'COMPETITION', 'Schedule a three-way call with the exec sponsor and champion to quantify the business case advantage over the incumbent''s discounted renewal.', 'The competitor_present flag indicates active intervention is required, triggering an AT_RISK verdict. The CDP incumbent has countered with a discounted renewal offer, creating pricing and switching-cost pressure despite strong executive engagement. Immediate action is needed to differentiate value beyond price before the customer defaults to the safer incumbent option.', 515, 143, 0.002214, 6865, NULL),
('reference|OPP-017', 'OPP-017', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'ECONOMIC_BUYER', 'Identify and schedule introductory meeting with corporate budget owner within the next week.', 'The opportunity has two active risk flags requiring intervention: no economic buyer identified and procurement not started. While the deal is early in discovery stage, the absence of a corporate budget owner is the most critical blocker for a $1.5M strategic deal. Plant-level support alone cannot move this forward without executive sponsorship.', 571, 135, 0.0022428, 6596, NULL),
('reference|OPP-018', 'OPP-018', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'ECONOMIC_BUYER', 'Schedule a meeting with the budget authority before the end of this quarter to validate funding and decision timeline.', 'The active risk flag indicates no economic buyer engagement, which is critical at this stage. Post-production leads are enthusiastic but lack purchasing authority, and 14 days of inactivity suggests momentum is stalling. Without budget holder involvement, this deal cannot progress reliably toward close.', 516, 131, 0.0021078000000000004, 6470, NULL),
('reference|OPP-019', 'OPP-019', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'COMPETITION', 'Schedule a meeting with the CIO to understand their preference for TelcoMetrics and differentiate our solution against their specific requirements.', 'The competitor_present flag indicates active risk requiring intervention. While we won the technical evaluation, TelcoMetrics remains in contention at the CIO''s insistence, creating a significant competitive threat during the commercial evaluation phase. The deal is in proposal stage awaiting scoring committee decision, making this the critical moment to address the competitive dynamic before losing control of the process.', 522, 166, 0.0024335999999999997, 6217, NULL),
('reference|OPP-020', 'OPP-020', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'SECURITY_LEGAL', 'Expedite the GxP validation questionnaire responses with the compliance team and schedule a joint call with the customer''s QA to resolve follow-ups this week.', 'Security and legal validation is blocking procurement engagement, creating a sequential dependency that puts the timeline at risk. The 12-day activity gap suggests momentum has stalled while waiting on compliance responses. Unblocking QA sign-off is the critical path to moving this deal forward.', 539, 175, 0.0025451999999999996, 6836, NULL),
('reference|OPP-021', 'OPP-021', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'ECONOMIC_BUYER', 'Request an introduction to the firm''s COO or managing partner who controls technology budget decisions.', 'The deal has been inactive for 25 days and no economic buyer is engaged—two partners saw the demo but neither controls the budget. The contact''s request to circle back suggests low urgency and lack of internal sponsorship. Without access to the decision-maker who owns technology spending, this opportunity cannot progress regardless of product interest.', 529, 148, 0.0022841999999999997, 7518, NULL),
('reference|OPP-022', 'OPP-022', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'ON_TRACK', 'NONE', 'Confirm CFO has received and reviewed the final pricing memo and establish a timeline for their decision.', 'The deal shows strong health indicators: 85% probability, negotiation stage, terms agreed in principle, successful reference call, and recent activity within 4 days. No active risk flags exist and the CFO pricing review is a standard final approval step. While not yet at contract stage with 90%+ probability, the deal is progressing normally through its natural closing sequence.', 516, 213, 0.0028458000000000003, 8918, NULL),
('reference|OPP-023', 'OPP-023', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'ECONOMIC_BUYER', 'Schedule a meeting with the VP of Digital and their budget authority to validate funding availability and approval process before advancing.', 'The deal has three active risk flags requiring intervention, with no economic buyer engagement being the most critical since the VP of Digital has not secured budget. Without budget authority and procurement awareness, this opportunity cannot progress regardless of technical fit. The 16 days of inactivity and early stage with 0.25 probability confirm this needs immediate attention.', 540, 160, 0.002412, 7283, NULL),
('reference|OPP-024', 'OPP-024', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'CHAMPION_LOSS', 'Schedule a joint call with the IT Director and CFO''s office to align on budget classification and confirm executive sponsorship.', 'The champion has been weakened by losing 40% of their team during a reorg, reducing their influence and capacity to drive the deal. Conflicting signals between Ops leadership (top-three initiative) and the CFO (discretionary/deferrable spend) indicate misalignment at the economic buyer level that could derail the opportunity. Immediate action is required to re-anchor executive sponsorship and resolve the budget classification conflict.', 540, 178, 0.002574, 7526, NULL),
('reference|OPP-025', 'OPP-025', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'INACTIVITY', 'Re-engage the admissions team immediately now that mid-August has passed and confirm next steps with cabinet stakeholders.', 'The deal has been inactive for 23 days, triggering the inactive_21d risk flag that requires intervention. While summer silence is normal in education, the admissions team should have returned by now and the deal remains stalled in early qualification stage. The positive pilot metrics and cabinet visibility are strong foundations, but momentum must be recaptured before the opportunity goes cold.', 521, 152, 0.0023058, 13217, NULL),
('reference|OPP-026', 'OPP-026', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'SECURITY_LEGAL', 'Engage executive sponsor to accelerate legal review and confirm BAA and HIPAA security rider are on track for closure within the remaining two-week window.', 'The deal is flagged as security_legal_blocked with BAA and HIPAA review in progress. While the two-week elapsed time is within normal cycle, the negotiation stage and high probability require proactive monitoring to prevent slippage. Clinical and IT alignment is strong, but legal clearance is the gating factor.', 529, 227, 0.0029952, 7208, NULL),
('reference|OPP-027', 'OPP-027', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'ECONOMIC_BUYER', 'Identify and schedule a meeting with the budget holder who controls studio funding decisions before the next title milestone.', 'The deal has two active risk flags requiring intervention: no economic buyer engagement and a competitor evaluation in progress. Without access to the budget holder, there is no path to close, especially since funding is milestone-dependent. The 15 days of inactivity and early stage with low probability confirm this opportunity needs immediate action to qualify properly.', 527, 153, 0.0023255999999999997, 7711, NULL),
('reference|OPP-028', 'OPP-028', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'PROCUREMENT', 'Confirm the procurement intake date in writing and secure executive sponsorship to expedite or parallel-track the process.', 'Procurement has not been engaged despite reaching proposal stage, creating timeline risk for the September 2026 close date. Although the sustainability office has selected the solution and the sponsor remains engaged, the deal cannot progress without formal procurement involvement. The known intake cycle provides a forcing function but requires confirmation and potential acceleration.', 525, 205, 0.00279, 8648, NULL),
('reference|OPP-029', 'OPP-029', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'NO_ACTION_NEEDED', 'CHAMPION_LOSS', 'Mark the opportunity as closed-lost and remove it from the forecast.', 'The close probability of 0.15 falls at or below the 0.1 threshold, indicating the deal is effectively dead. The champion has left for a competitor, the replacement contact lacks authority and has been unresponsive for five weeks, and the opportunity remains stuck in early qualification stage. No intervention will salvage this deal.', 523, 139, 0.0021924, 7281, NULL),
('reference|OPP-030', 'OPP-030', 'reference', NULL, 'premium', 'claude-sonnet-4-5', 'AT_RISK', 'ECONOMIC_BUYER', 'Confirm funding timeline and decision authority with the CFO or board member overseeing Series C before advancing the proposal.', 'The Engineering VP''s verbal commitment conflicts with internal documentation showing the project is paused for Series C funding, indicating the VP may not control budget authority. The 0.7 probability reflects optimism rather than validated economic buyer commitment. This deal requires immediate clarification of funding timeline and true decision-making authority before the forecast can be trusted.', 533, 226, 0.0029934000000000002, 8637, NULL),
('adaptive_0.98|OPP-001', 'OPP-001', 'adaptive', 0.98, 'cheap', 'llama3.1-8b', 'NO_ACTION_NEEDED', 'NONE', 'Monitor the opportunity for the expected countersignature from the customer.', 'The opportunity is in the CONTRACT stage with a high close probability of 0.99 and no active risk flags. The legal review is complete, MSA redlines are signed off, and a PO has been raised in the customer''s system. The rep expects countersignature this month, which is the only remaining step before closing the deal.', 469, 113, 7.6824e-05, 3797, NULL),
